from python_wrap.presets import http_client

users_api = http_client("users", timeout_seconds=3)

@users_api
def get_user(user_id: int) -> dict[str, int]:
    return {"id": user_id}  # call your HTTP client here

assert get_user(7) == {"id": 7}

from python_wrap import retry, timeout

@retry(max_attempts=3, delay=0.01, on=ConnectionError)
@timeout(2)
def fetch() -> str:
    return "ok"

assert fetch() == "ok"

from python_wrap import RateLimitExceeded, rate_limit

@rate_limit(calls=2, period=60)
def ping() -> str:
    return "pong"

ping()
ping()
try:
    ping()
except RateLimitExceeded:
    pass

from python_wrap import circuit_breaker

@circuit_breaker(failure_threshold=5, recovery_timeout=30, on=ConnectionError)
def call_vendor() -> str:
    return "ok"

assert call_vendor() == "ok"

from python_wrap import timeout

@timeout(2)
def compute() -> int:
    return 42

assert compute() == 42

from python_wrap import memoize

@memoize(ttl=60, maxsize=1024)
def price(sku: str) -> int:
    return len(sku)

assert price("A-1") == price("A-1") == 3

from python_wrap import singleflight

@singleflight
def load(key: str) -> str:
    return key.upper()

assert load("a") == "A"

from python_wrap import limit_concurrency

@limit_concurrency(4)
def query() -> str:
    return "rows"

assert query() == "rows"

from python_wrap import fallback

@fallback([], on=ConnectionError)
def recommendations() -> list[str]:
    raise ConnectionError

assert recommendations() == []

from python_wrap import retry
from python_wrap.testing import fake_clock

@retry(max_attempts=3, delay=5, on=ValueError)
def flaky() -> None:
    raise ValueError

with fake_clock() as clock:
    try:
        flaky()
    except ValueError:
        pass
assert len(clock.sleeps) == 2
